solution.sanitized:
def retry_schedule(attempts, delay, cap):
    if attempts < 0 or delay <= 0 or cap <= 0:
        raise ValueError("schedule")
    times, elapsed = [], 0
    for index in range(attempts):
        times.append(elapsed)
        elapsed += min(cap, delay * 2 ** index)
    return times

